using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class FogTransportOperations
{
    public void step(Settings state,Settings config,double dt)
    {
        if(dt<=0||!double.IsFinite(dt))return;int n=state["fog_n"].AsInt32();var h=state["fog_size"].AsVector3()/n;double maximum=0;foreach(var v in state["fog_velocity"].AsVector3Array())if(v.IsFinite())maximum=Math.Max(maximum,Math.Max(Math.Abs(v.X),Math.Max(Math.Abs(v.Y),Math.Abs(v.Z))));var wind=Vector(config,"wind",Vector3.Zero);maximum=Math.Max(maximum,Math.Max(Math.Abs(wind.X),Math.Max(Math.Abs(wind.Y),Math.Abs(wind.Z))));int substeps=(int)Math.Clamp(Math.Ceiling(maximum*dt/Math.Max(.0001,Math.Min(h.X,Math.Min(h.Y,h.Z)))*6/.8),1,8);for(int i=0;i<substeps;i++)substep_state(state,config,dt/substeps);state["fog_step"]=state["fog_step"].AsInt64()+1;
    }
    public void substep_state(Settings state,Settings config,double duration)
    {
        float dt=(float)duration;int n=state["fog_n"].AsInt32();var size=state["fog_size"].AsVector3();var h=size/n;var data=grid(n);var positions=data["positions"].AsVector3Array();var neighbors=data["neighbors"].AsInt32Array();int count=positions.Length;var rho=state["fog_density"].AsFloat32Array();var old=state["fog_velocity"].AsVector3Array();var solid=state["fog_solid"].AsByteArray();var boundary=state["fog_boundary_velocity"].AsVector3Array();var v=(Vector3[])old.Clone();double time=Number(state,"fog_time")+duration;var wind=Vector(config,"wind",Vector3.Zero);float response=(float)(1-Math.Exp(-Math.Max(0,Number(config,"wind_response",2))*duration)),damping=(float)Math.Exp(-Math.Max(0,Number(config,"damping",.1))*duration),turbulence=(float)Number(config,"turbulence"),scale=(float)Math.Max(.001,Number(config,"turbulence_scale",1));double phase=time*Number(config,"turbulence_frequency",1)+Number(config,"seed",1)*1.732;var fields=config.GetValueOrDefault("fields",new GArray()).AsGodotArray();
        for(int i=0;i<count;i++){if(solid[i]!=0){v[i]=boundary[i];continue;}var p=positions[i]*size;var flow=velocity_sample(old,solid,p-old[i]*dt,size,n)*damping;flow=flow.Lerp(wind,response);var q=p/scale;var curl=new Vector3((float)(Math.Sin(q.Z+phase)+Math.Cos(q.Y-phase)),(float)(Math.Sin(q.X+phase)+Math.Cos(q.Z-phase)),(float)(Math.Sin(q.Y+phase)+Math.Cos(q.X-phase)));flow+=(curl*turbulence+field_acceleration(fields,p,time)+Vector(config,"buoyancy_direction",Vector3.Up)*(float)Number(config,"buoyancy")*rho[i])*dt;v[i]=flow.IsFinite()?flow:Vector3.Zero;}
        bool closed=config.GetValueOrDefault("closed",false).AsBool();v=project(v,solid,boundary,neighbors,h,duration,Math.Clamp((int)Number(config,"pressure_iterations",6),0,32),closed,state);float limit=Math.Min(h.X,Math.Min(h.Y,h.Z))*.8f/(6*dt),expansion=(float)Number(config,"expansion");for(int i=0;i<count;i++){if(solid[i]!=0)continue;v[i]+=positions[i]*expansion;if(!v[i].IsFinite()){v[i]=Vector3.Zero;state["fog_clamped"]=true;}var bounded=v[i].Clamp(-Vector3.One*limit,Vector3.One*limit);if(bounded!=v[i])state["fog_clamped"]=true;v[i]=bounded;}
        var delta=new float[count];double lost=0;for(int i=0;i<count;i++){if(solid[i]!=0)continue;for(int axis=0;axis<3;axis++){int j=neighbors[i*6+axis*2+1];if(j>=0&&solid[j]==0){float speed=(v[i][axis]+v[j][axis])*.5f,amount=speed*dt/h[axis]*(speed>=0?rho[i]:rho[j]);delta[i]-=amount;delta[j]+=amount;}else if(j<0&&!closed){float amount=Math.Max(0,v[i][axis])*dt/h[axis]*rho[i];delta[i]-=amount;lost+=amount;}if(neighbors[i*6+axis*2]<0&&!closed){float amount=Math.Max(0,-v[i][axis])*dt/h[axis]*rho[i];delta[i]-=amount;lost+=amount;}}}for(int i=0;i<count;i++)rho[i]=Math.Max(0,rho[i]+delta[i]);
        float diffusion=(float)Math.Max(0,Number(config,"diffusion"));if(diffusion>0){Array.Clear(delta);for(int i=0;i<count;i++){if(solid[i]!=0)continue;for(int axis=0;axis<3;axis++){int j=neighbors[i*6+axis*2+1];if(j<0||solid[j]!=0)continue;float amount=(rho[i]-rho[j])*Math.Min(1f/6,diffusion*dt/(h[axis]*h[axis]));delta[i]-=amount;delta[j]+=amount;}}for(int i=0;i<count;i++)rho[i]=Math.Max(0,rho[i]+delta[i]);}
        double dissipation=Math.Max(0,Number(config,"dissipation")),maximum=Math.Max(.01,Number(config,"max_density",32));var sink=config.GetValueOrDefault("sink_mask",System.Array.Empty<float>()).AsFloat32Array();for(int i=0;i<count;i++){double value=rho[i]*Math.Exp(-dissipation*duration*(sink.Length==count?sink[i]:1));lost+=rho[i]-value;double bounded=Math.Min(value,maximum);lost+=value-bounded;rho[i]=(float)bounded;}state["fog_density"]=rho;state["fog_velocity"]=v;state["fog_time"]=time;state["fog_lost"]=Number(state,"fog_lost")+lost*size.X*size.Y*size.Z/count;
    }
    public Vector3[] project(Vector3[] v,byte[] solid,Vector3[] boundary,int[] neighbors,Vector3 h,double duration,int iterations,bool closed,Settings state)
    {
        float dt=(float)duration;int count=v.Length;var pressure=state["fog_pressure"].AsFloat32Array();var divergence=new float[count];var weights=Vector3.One/(h*h);float largest=0;
        for(int i=0;i<count;i++){if(solid[i]!=0)continue;float sum=0;for(int axis=0;axis<3;axis++)for(int side=0;side<2;side++){int j=neighbors[i*6+axis*2+side];float face=v[i][axis];if(j>=0)face=solid[j]==0?(v[i][axis]+v[j][axis])*.5f:boundary[j][axis];else if(closed)face=0;sum+=face*(side==1?1:-1)/h[axis];}divergence[i]=sum/dt;largest=Math.Max(largest,Math.Abs(divergence[i]));}if(largest<.000001f){Array.Clear(pressure);iterations=0;}
        for(int iteration=0;iteration<iterations;iteration++){var next=(float[])pressure.Clone();for(int i=0;i<count;i++){if(solid[i]!=0){next[i]=0;continue;}float sum=0,denominator=0;for(int axis=0;axis<3;axis++)for(int side=0;side<2;side++){int j=neighbors[i*6+axis*2+side];if(j>=0&&solid[j]==0){sum+=pressure[j]*weights[axis];denominator+=weights[axis];}else if(j<0&&!closed)denominator+=weights[axis];}float value=denominator>0?(sum-divergence[i])/denominator:0;next[i]=float.IsFinite(value)?value:0;}pressure=next;}
        for(int i=0;i<count;i++){if(solid[i]!=0)continue;var value=v[i];for(int axis=0;axis<3;axis++){int minus=neighbors[i*6+axis*2],plus=neighbors[i*6+axis*2+1];float a=minus>=0&&solid[minus]==0?pressure[minus]:minus>=0||closed?pressure[i]:0,b=plus>=0&&solid[plus]==0?pressure[plus]:plus>=0||closed?pressure[i]:0;value[axis]-=dt*(b-a)/(2*h[axis]);if(plus>=0&&solid[plus]!=0)value[axis]=Math.Min(value[axis],boundary[plus][axis]);else if(plus<0&&closed)value[axis]=Math.Min(value[axis],0);if(minus>=0&&solid[minus]!=0)value[axis]=Math.Max(value[axis],boundary[minus][axis]);else if(minus<0&&closed)value[axis]=Math.Max(value[axis],0);}v[i]=value;}state["fog_pressure"]=pressure;return v;
    }
}
